add_filter( 'woocommerce_product_filters', 'perfectpixel_products_taxonomy_filter' );

function perfectpixel_products_taxonomy_filter( $output ) {
	$taxonomy = sanitize_key( '{{admin_filter_taxonomy}}' );
	$tax      = get_taxonomy( $taxonomy );
	if ( ! $tax ) {
		return $output;
	}
	// Taxonomies registered with query_var filter the list through their own query var.
	$output .= wp_dropdown_categories(
		array(
			'taxonomy'        => $taxonomy,
			'name'            => $tax->query_var ? $tax->query_var : $taxonomy,
			'value_field'     => 'slug',
			'show_option_all' => $tax->labels->all_items,
			'selected'        => isset( $_GET[ $tax->query_var ? $tax->query_var : $taxonomy ] ) ? sanitize_title( wp_unslash( $_GET[ $tax->query_var ? $tax->query_var : $taxonomy ] ) ) : '',
			'hide_empty'      => true,
			'hierarchical'    => $tax->hierarchical,
			'show_count'      => true,
			'echo'            => false,
		)
	);
	return $output;
}
